#!/usr/bin/env node
/**
 * Windows 11 通知 Hook - Claude Code 任务完成通知
 * 在任务结束时发送 Windows Toast 通知
 */

const { execSync } = require('child_process');
const path = require('path');

// 获取脚本目录
const scriptDir = __dirname;
const psScriptPath = path.join(scriptDir, 'notify-windows.ps1');

// 获取环境变量或使用默认值
const sessionId = process.env.CLAUDE_SESSION_ID || 'unknown';
const timestamp = new Date().toLocaleString('zh-CN', {
  hour12: false,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit'
});

// 构建通知内容
const title = 'Claude Code - 任务完成';
const message = `会话结束\n时间: ${timestamp}`;

try {
  // 执行 PowerShell 脚本
  const psCommand = `powershell.exe -ExecutionPolicy Bypass -File "${psScriptPath}" -Title "${title}" -Message "${message}"`;

  execSync(psCommand, {
    stdio: 'inherit',
    windowsHide: true
  });

  console.log('✓ Windows notification triggered');
} catch (error) {
  console.error('✗ Failed to send notification:', error.message);
  // 不抛出错误，避免阻塞主流程
}
